\begin{exercise}
\label{exer:codazzi-tensor-characterization}
\dcref{ch8:8.20}
Show that a smooth 2-tensor field $h$ on a Riemannian manifold is a Codazzi tensor if and only if both $h$ and $\nabla h$ are symmetric.
\end{exercise}

